using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using Tulaziva.Domain.Entities;

namespace Tulaziva.Infrastructure.Persistence.Configurations;

public class CategoryConfiguration : IEntityTypeConfiguration<Category>
{
    public void Configure(EntityTypeBuilder<Category> builder)
    {
        builder.ToTable("Categories");

        // The ids are fixed (see DefaultCategories), not generated by the database.
        builder.HasKey(c => c.Id);
        builder.Property(c => c.Id).ValueGeneratedNever();

        builder.Property(c => c.Key).IsRequired().HasMaxLength(50);
        builder.HasIndex(c => c.Key).IsUnique();

        builder.HasData(DefaultCategories.All);
    }
}

public class AdConfiguration : IEntityTypeConfiguration<Ad>
{
    public void Configure(EntityTypeBuilder<Ad> builder)
    {
        builder.ToTable("Ads");

        builder.HasKey(a => a.Id);

        builder.Property(a => a.Title).IsRequired().HasMaxLength(120);
        builder.Property(a => a.Description).IsRequired().HasMaxLength(4000);
        builder.Property(a => a.Price).HasPrecision(18, 2);
        builder.Property(a => a.Currency).IsRequired().HasMaxLength(3).IsFixedLength().IsUnicode(false);
        builder.Property(a => a.Status).HasConversion<string>().HasMaxLength(20).IsRequired();

        // A user is not deleted with its ads: the files of the ads would stay orphaned.
        builder.HasOne(a => a.Owner).WithMany().HasForeignKey(a => a.OwnerId).OnDelete(DeleteBehavior.Restrict);
        builder.HasOne(a => a.Category).WithMany().HasForeignKey(a => a.CategoryId).OnDelete(DeleteBehavior.Restrict);

        builder.HasIndex(a => a.OwnerId);
        builder.HasIndex(a => new { a.Status, a.ExpiresAtUtc });
        builder.HasIndex(a => new { a.CategoryId, a.Status });
        builder.HasIndex(a => new { a.Latitude, a.Longitude });
    }
}

public class AdImageConfiguration : IEntityTypeConfiguration<AdImage>
{
    public void Configure(EntityTypeBuilder<AdImage> builder)
    {
        builder.ToTable("AdImages");

        builder.HasKey(i => i.Id);

        builder.Property(i => i.StoragePath).IsRequired().HasMaxLength(300);
        builder.Property(i => i.ContentType).IsRequired().HasMaxLength(50);

        builder.HasOne(i => i.Ad).WithMany(a => a.Images).HasForeignKey(i => i.AdId).OnDelete(DeleteBehavior.Cascade);
        builder.HasIndex(i => new { i.AdId, i.Position });
    }
}
